"""Render the frozen human-label evaluation and complete per-input comparison."""
import json
from pathlib import Path
P=Path('output/human-notes-public-evaluation')
def main():
 manifest=json.loads((P/'annotation_manifest.json').read_text());metrics=json.loads((P/'metrics.json').read_text());rows=json.loads((P/'all139_predictions.json').read_text())
 pure=json.loads((P/'tfidf_only_metrics.json').read_text()) if (P/'tfidf_only_metrics.json').exists() else None
 best='adaptive_0_3__per_category'
 lines=['# Проверка моделей по предоставленным человеческим заметкам','',
'**Среди сложных моделей ранее выбранный по calibration depth6 + TF-IDF получил Micro-F1=0.910345 на37 объявлениях с однозначными human_labels; Precision=0.868421, Recall=0.956522, TP66/FP10/FN3, полностью верно30/37. Отдельный чистый TF-IDF+SGD дал0.924138, TP67/FP9/FN2 и31/37 полностью верных ответов: на этом маленьком поднаборе он оказался лучше сложных моделей. Веса и пороги всех моделей заморожены, адаптации к human labels не было.**','',
'## Что действительно размечено','',
'Файл содержит139 уникальных описаний прежнего public test208, все208 исходных индексов покрыты один раз. Явные human_labels есть у38 уникальных объявлений:37 однозначных и1 с альтернативами. У101 нет новой человеческой метки. Поэтому единого «нового human-F1 на всех139» получить нельзя без додумывания разметки. Для всех139 сохранены предсказания и происхождение доступных меток.','',
'Основная оценка использует37 уникальных объявлений по одному разу, без размножения дубликатов. В них17 пустых gold,20 непустых, всего69 положительных целевых меток. Вариант «[] или все5» у объявления19/исходной строки20 исключён из основного расчёта. Оговорки в комментариях при явно выбранной единственной метке сохранены как часть аннотации, не заменены нашими решениями.','',
'Этот поднабор соответствует первым размеченным объявлениям файла, не случайной выборке; он маленький и не независимый от прежнего public. Итог нельзя переносить на все139,208 или скрытый тест.','',
'## Фиксированные модели','',
'Лучший по прежнему calibration вариант — adaptive_0_3: depth6, TF-IDF probability как41-й признак, прежние индивидуальные пороги [0.6,0.525,0.375,0.375,0.25]. Он выбран ранее по calibration, а не по этим заметкам. Дополнительно фиксированно проверены прежний лучший вариант с общим0.5 (depth8), C_syntax+60 и исходная C_syntax. Ни один порог здесь не подбирался.','',
'Свежий инференс CatBoost на сохранённых признаках исходных объявлений точно воспроизвёл прежние вероятности для всех208 строк (max diff<1e-12). Все139 описаний совпадают с прежними после нормализации пробелов/регистра и дают одинаковые чанки. У3 транскриптов отличаются сырые символы/переносы; для сопоставимости использованы исходные canonical description из parquet, включая исходную длину. Title и заметки в модель не подавались. Qwen/SGD не переобучались и не пересчитывались.','',
'| Модель | Human Micro-F1 | Precision | Recall | TP | FP | FN | Полностью верно |','|---|---:|---:|---:|---:|---:|---:|---:|']
 for name,d in metrics.items():
  r=d['human_resolved37'];lines.append(f"| {d['label']} | {r['micro_f1']:.6f} | {r['precision']:.4f} | {r['recall']:.4f} | {r['tp']} | {r['fp']} | {r['fn']} | {r['fully_correct_ads']}/37 |")
 if pure:
  r=pure['human_resolved37'];lines.append(f"| Чистый TF-IDF+SGD, тот же train6319 | {r['micro_f1']:.6f} | {r['precision']:.4f} | {r['recall']:.4f} | {r['tp']} | {r['fp']} | {r['fn']} | {r['fully_correct_ads']}/37 |")
  lines+=['','Преимущество чистого TF-IDF над лучшим сложным вариантом здесь1.379п.п. Парный bootstrap5000 по37 уникальным объявлениям даёт95%CI разницы [−3.000;+6.935]п.п., включая0. На этом поднаборе TF-IDF лучший по наблюдаемым числам; устойчивое превосходство в целом не доказано. На прежнем V3test600 TF-IDF имелF10.692625, исходная C_syntax0.915916: перенос между доменами резко различается. Полные сравнения — paired_tfidf_comparisons.json.']
 lines+=['','## На тех же37: прежние и уточнённые метки','',
'Для этой диагностической таблицы старый gold взят из первой явно указанной исходной строки каждой группы. В конфликтных группах единого старого gold нет; выбор первой строки не является переразметкой и не разрешает конфликт. Поэтому это условное сравнение эталонов на тех же входах, а не улучшение модели и не новый score всего208.','',
'| Модель | Старый gold первой строки | Human labels |','|---|---:|---:|']
 for name,d in metrics.items():lines.append(f"| {d['label']} | {d['original_gold_same37']['micro_f1']:.6f} | {d['human_resolved37']['micro_f1']:.6f} |")
 lines+=['','При неизменных предсказаниях значительная часть расхождений снимается предоставленными метками. Например, исходная C_syntax на том же37 меняется с0.692308 на0.897959 только из-за эталона. Это не означает, что «истинный F1 на всём public равен0.898»: остальная разметка не пересмотрена, выборка мала, некоторые новые решения спорны.','',
'## Оставшиеся ошибки лучшего по calibration варианта','',
'| Объявление MD | Строки public | Human labels | Prediction |','|---:|---|---|---|']
 errors=[r for r in rows if r['annotation_status']=='human_resolved' and r['human_gold']!=r['predictions'][best]]
 for r in errors:lines.append(f"| {r['item_number']} | {r['official_rows']} | {r['human_gold']} | {r['predictions'][best]} |")
 lines+=['','По предоставленной разметке среди17 пустых объявлений лучший сложный вариант ошибается в3, создав8 FP. Это объявления4 (перечисление целевых услуг только в поисковом хвосте),18 (пустая метка из-за условия «частичные работы не выполняем») и25 (электрика в техническом проекте). Решение разметчика по18 требует отдельного согласования с ТЗ. Чистый TF-IDF ошибается в2 из17 пустых объявлений, создавая7 FP.','',
'## Спорные места в предоставленных заметках — gold не изменён','',
'- Объявление6/строка6: «Внутренняя отделка, шпатлёвка, гипсокартон», human=[102]. Справочник102 описывает оштукатуривание составами,106 включает шпаклёвку. Предоставленная метка102 остаётся в оценке, но не является бесспорным эталоном.','- Объявление18/строка18: human=[] объяснён запретом на частичные работы, хотя далее есть явный список выполняемых плиточных, сантехнических, электрических и отделочных работ. По ТЗ запрет обещать отдельный заказ относится к генерации, а не автоматически отменяет классификацию реально предложенных работ. Здесь требуется согласование правила разметки; мы не подменяли человеческий gold.','- Объявление19/строка20: автор оставил варианты [] и все102–106. Оно исключено из основных37, предсказания доступны в реестре139.','- Выравнивание без названного способа, SEO-перечни и общий ремонт остаются семантически пограничными случаями. Наличие human_labels означает предоставленное решение, а не доказанную безошибочность аннотации.','',
'## Полные тексты семи расхождений','']
 for r in errors:
  lines +=[f"### Объявление {r['item_number']}, public {r['official_rows']}",'',f"Source101; human={r['human_gold']}; прежние варианты gold={r['original_gold_variants']}; prediction лучшего={r['predictions'][best]}.",'','```text',r['canonical_description'],'```','',f"Другие фиксированные ответы: {json.dumps(r['predictions'],ensure_ascii=False)}",'']
 lines+=['## Реестр всех139 входов','',
'Полные входы, предоставленные заметки, варианты gold и ответы всех моделей — all139_predictions.json. Ниже краткий реестр, без назначения меток отсутствующим строкам.','',
'| MD | Public rows | Статус | Human | Лучший по calibration | C_syntax+60 |','|---:|---|---|---|---|---|']
 for r in rows:lines.append(f"| {r['item_number']} | {r['official_rows']} | {r['annotation_status']} | {r['human_label_options']} | {r['predictions'][best]} | {r['predictions']['C_syntax_plus60_fixed_05']} |")
 lines+=['','## Воспроизведение','',
'Неизменённая копия предоставленного MD: datasets/public_review_139/public_test_139_unique_with_notes.md. SHA256: '+manifest['source_sha256']+'.','',
'Скрипты parse_annotations.py, evaluate.py и build_report.py запускаются из корня проекта через /tmp/innopolis-qwen-emb-venv/bin/python. evaluate.py отказывается перезаписывать уже полученные метрики. Параметры, вероятности, пороги и provenance сохранены. Никакой подстройки наhuman37 или преобразования101 отсутствующей человеческой метки в[] нет. Эксперимент с исправлением признаков выполняется в другом worktree и не использует эти заметки для обучения/отбора.','']
 (P/'report.md').write_text('\n'.join(lines))
 print('Report saved:',len(errors),'full mismatches;37 human-resolved;139 predictions.')
if __name__=='__main__':main()
